 const out={id:id(v.id),version:version(v.version),status:v.status,cardCode:text(v.cardCode,64,true),phoneNumber:text(v.phoneNumber,40,true),carrier:text(v.carrier,100),planDescription:text(v.planDescription,1000),planExpiresOn:v.planExpiresOn,notes:text(v.notes,2000),accounts:accounts(v.accounts),createdAt:v.createdAt,updatedAt:v.updatedAt};
 if(v.planExpiresOn!==null&&!validDate(v.planExpiresOn))throw new ContractError('套餐到期日期无效。');
