function page(v,adapt){if(!obj(v)||!Array.isArray(v.rows)||v.rows.length>50||!Number.isSafeInteger(v.total)||v.total<0||!Number.isSafeInteger(v.offset)||v.offset<0||v.limit!==50||(v.rows.length&&v.offset+v.rows.length>v.total))throw new ContractError('手机卡分页资料不完整。');return {rows:v.rows.map(adapt),total:v.total,offset:v.offset,limit:50};}
