 if(!/^\+?[0-9][0-9 ()-]{2,39}$/.test(out.phoneNumber)||out.phoneNumber.replace(/\D/g,'').length<3||new Set(out.accountIds).size!==out.accountIds.length||(out.planExpiresOn!==null&&!validDate(out.planExpiresOn)))throw new ContractError('请核对号码、账号关联和套餐日期。');if(expected!==undefined)out.expectedVersion=version(expected);return out;
