export function phoneCardIdentityPayload(v){if(!obj(v)||Object.keys(v).some(k=>!['requestKey','expectedVersion','expectedCardVersion','registeredEntity','reason'].includes(k))||!Object.hasOwn(v,'registeredEntity'))throw new ContractError();return {requestKey:id(v.requestKey),expectedVersion:version(v.expectedVersion,true),expectedCardVersion:version(v.expectedCardVersion),registeredEntity:v.registeredEntity===null?null:text(v.registeredEntity,200,true),reason:text(v.reason,2000,true)};}
export function phoneCardResult(v,owner,action){if(!obj(v)||(owner&&v.id!==owner)||(action&&v.action!==action))throw new ContractError('手机卡回执不匹配。');return {id:id(v.id),version:version(v.version)};}
